const transcript = $json.text || '';
const data = $('Webhook Sprachmemo').first().json.body || {};
const kategorie = data.kategorie || 'spartipps';
const customTitle = data.titel || '';

// Füllwörter bereinigen
let cleaned = transcript
  .replace(/\b(äh+|ähm+|öh+|öhm+|sozusagen|quasi|halt|wie gesagt)\b/gi, '')
  .replace(/\s+/g, ' ')
  .trim();

const today = new Date().toISOString().split('T')[0];
const slug = (customTitle || cleaned.slice(0, 45))
  .toLowerCase()
  .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '');

const title = customTitle || (cleaned.slice(0, 55).trim() + ' – Der Praxis-Check');
const wordCount = cleaned.split(' ').length;
const readingTime = Math.max(1, Math.round(wordCount / 160));

const markdown = `---` +
`\ntitle: "${title}"` +
`\ndate: ${today}T08:00:00+02:00` +
`\ndraft: true` +
`\nauthor: "Frank Hartung"` +
`\ndescription: "${cleaned.slice(0, 150)}..."` +
`\ncategories: ["${kategorie}"]` +
`\ntags: ["${kategorie}", "fixkosten", "spartipps", "whisper-diktat"]` +
`\nreadingTime: ${readingTime}` +
`\n---` +
`\n\n## Auf den Punkt: Das Wichtigste in Kürze` +
`\n\n> **Franks Praxis-Fazit:** Mit dem planvollen 4K-Prüfpfad senkst du deine monatlichen Fixkosten spürbar und sicher.` +
`\n\n${cleaned}` +
`\n\n---` +
`\n\n## Der 4K-Prüfpfad für diesen Ratgeber` +
`\n1. **Kosten sehen:** Reale Ausgaben erfassen.` +
`\n2. **Konditionen rechnen:** Leistungen genau vergleichen.` +
`\n3. **Kündigungsfenster sichern:** Fristen im Kalender vormerken.` +
`\n4. **Kurs halten:** Einmal jährlich Verträge nachjustieren.` +
`\n\n---` +
`\n*Erstellt via 0 € Whisper-Pipeline auf Profi-Agentur-Niveau.*`;

return [{
  json: {
    slug: `${today}-${slug}`,
    title,
    kategorie,
    wordCount,
    readingTime,
    markdown,
    cleanedText: cleaned
  }
}];
